/**
 * Keep the two 3 mL production stocks pixel-identical except cake color.
 *
 * The locked white source contains a rectangular matte behind the powder.
 * The locked blue source has the correct clean glass, cap, cake geometry, and
 * texture, so the production white derivative is generated by neutralizing
 * only cobalt cake pixels. Locked masters are never modified.
 */
import fs from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import sharp from "sharp";

const scriptDir = path.dirname(fileURLToPath(import.meta.url));
const systemRoot = path.resolve(scriptDir, "..");
const repoRoot = path.resolve(systemRoot, "..");
const sourcePath = path.join(
  systemRoot,
  "locked-masters/vials/02_3mL_Cobalt_Blue_Powder_LOCKED.png"
);
const assetPath = path.join(
  systemRoot,
  "assets/vials/UD_3mL_White_Peptide_Black_Cap_Unlabeled.png"
);
const publicPath = path.join(
  repoRoot,
  "public/ud-labels/vials/UD_3mL_White_Peptide_Black_Cap_Unlabeled.png"
);

const { data, info } = await sharp(sourcePath)
  .ensureAlpha()
  .raw()
  .toBuffer({ resolveWithObject: true });

let changed = 0;
for (let y = 0; y < info.height; y += 1) {
  for (let x = 0; x < info.width; x += 1) {
    const index = (y * info.width + x) * info.channels;
    const r = data[index];
    const g = data[index + 1];
    const b = data[index + 2];

    // Cobalt cake only. Spatial guard protects the blue-black studio glass.
    const inCakeRegion =
      x >= info.width * 0.2 &&
      x <= info.width * 0.94 &&
      y >= info.height * 0.70 &&
      y <= info.height * 0.91;
    const cobalt = b > 40 && b > r + 12 && b > g + 4;
    if (!inCakeRegion || !cobalt) continue;

    // Preserve the cake's granular relief while mapping cobalt to neutral white.
    const gray = Math.max(145, Math.min(255, Math.round(118 + b * 0.58)));
    data[index] = gray;
    data[index + 1] = gray;
    data[index + 2] = gray;
    changed += 1;
  }
}

const png = await sharp(data, {
  raw: {
    width: info.width,
    height: info.height,
    channels: info.channels,
  },
})
  .png({ compressionLevel: 9, adaptiveFiltering: true })
  .toBuffer();

await Promise.all([
  fs.mkdir(path.dirname(assetPath), { recursive: true }),
  fs.mkdir(path.dirname(publicPath), { recursive: true }),
]);
for (const outputPath of [assetPath, publicPath]) {
  await fs.unlink(outputPath).catch((error) => {
    if (error?.code !== "ENOENT") throw error;
  });
  await fs.writeFile(outputPath, png);
}

console.log(
  JSON.stringify(
    {
      sourcePath,
      assetPath,
      publicPath,
      width: info.width,
      height: info.height,
      neutralizedCakePixels: changed,
    },
    null,
    2
  )
);
